pub fn updateLockTryAcquire(executable_path: []const u8) ?UpdateLock {
    var buf: [std.fs.max_path_bytes]u8 = undefined;
    const lock_path = cio.bufPrintZ(&buf, "{s}.update.lock", .{executable_path}) catch return null;

    if (builtin.os.tag == .windows) {
        const path_w = std.unicode.utf8ToUtf16LeAllocZ(std.heap.page_allocator, lock_path) catch return null;
        defer std.heap.page_allocator.free(path_w);
        const handle = CreateFileW(path_w.ptr, generic_read | generic_write, 0, null, open_always, 0, null);
        if (handle == invalid_handle_value) return null;
        return handle;
    }

    const fd = std.c.open(lock_path.ptr, .{ .ACCMODE = .RDWR, .CREAT = true }, @as(c_uint, 0o600));
    if (fd < 0) return null;
    if (std.c.flock(fd, std.c.LOCK.EX | std.c.LOCK.NB) != 0) {
        _ = std.c.close(fd);
        return null;
    }
    return fd;
}

pub fn updateLockRelease(lock: UpdateLock) void {
    if (builtin.os.tag == .windows) {
        _ = CloseHandle(lock);
        return;
    }
    _ = std.c.flock(lock, std.c.LOCK.UN);
    _ = std.c.close(lock);
}

