pub fn replaceBinaryWithRollback(io: std.Io, replacement_path: []const u8, dest_path: []const u8, old_path: []const u8) !void {
    std.Io.Dir.deleteFileAbsolute(io, old_path) catch {};

    const moved_old = blk: {
        std.Io.Dir.renameAbsolute(dest_path, old_path, io) catch break :blk false;
        break :blk true;
    };

    std.Io.Dir.renameAbsolute(replacement_path, dest_path, io) catch |install_err| {
        if (moved_old) {
            std.Io.Dir.renameAbsolute(old_path, dest_path, io) catch return error.UpdateRollbackFailed;
        }
        return install_err;
    };
}

